const longitudes = [-150, -120, -90, -60, -30, 0, 30, 60, 90, 120, 150] as const;
const latitudes = [-60, -30, 0, 30, 60] as const;
const ringRadii = [66, 156, 271, 362, 433] as const;
const spokes = Array.from({length: 12}, (_, index) => index * 30);
const ticks = Array.from({length: 120}, (_, index) => index * 3);

const hash = (value: number) => {
  const x = Math.sin(value * 127.1 + 311.7) * 43758.5453123;
  return x - Math.floor(x);
};

const specks = Array.from({length: 110}, (_, index) => ({
  x: hash(index + 2) * WIDTH,
  y: hash(index + 71) * HEIGHT,
  radius: 0.7 + hash(index + 131) * 1.8,
  opacity: 0.08 + hash(index + 193) * 0.22,
  phase: hash(index + 241) * TWO_PI,
}));

const normalizeAngle = (value: number) => ((value % 360) + 360) % 360;

const project = (lon: number, lat: number): Point => [
  MAP_LEFT + ((lon + 180) / 360) * MAP_WIDTH,
  MAP_TOP + ((90 - lat) / 180) * MAP_HEIGHT,
];

const polar = (radius: number, angleDegrees: number): Point => {
  const angle = (angleDegrees * Math.PI) / 180;
  return [
    CENTER_X + Math.cos(angle) * radius,
    CENTER_Y + Math.sin(angle) * radius,
  ];
};

const sectorPath = (
  radius: number,
  startDegrees: number,
  endDegrees: number,
) => {
  const start = polar(radius, startDegrees);
  const end = polar(radius, endDegrees);
  const largeArc = Math.abs(endDegrees - startDegrees) > 180 ? 1 : 0;
  return [
    `M ${CENTER_X} ${CENTER_Y}`,
    `L ${start[0]} ${start[1]}`,
    `A ${radius} ${radius} 0 ${largeArc} 1 ${end[0]} ${end[1]}`,
    "Z",
  ].join(" ");
};

const SWEEP_WIDE = sectorPath(SWEEP_RADIUS, -72, 0);

const cityPoints = cities.map((city) => project(city.lon, city.lat));

const connectionPath = (from: Point, to: Point) => {
  const dx = to[0] - from[0];
  const dy = to[1] - from[1];
  const distance = Math.sqrt(dx * dx + dy * dy);
  const curve = Math.min(120, Math.max(26, distance * 0.11));
  const midpointX = (from[0] + to[0]) / 2;
  const midpointY = (from[1] + to[1]) / 2 - curve;
  return `M ${from[0]} ${from[1]} Q ${midpointX} ${midpointY} ${to[0]} ${to[1]}`;
};

const distanceFromCenter = (point: Point) => {
  const dx = point[0] - CENTER_X;
  const dy = point[1] - CENTER_Y;
  return Math.sqrt(dx * dx + dy * dy);
};

const pointAngle = (point: Point) =>
  normalizeAngle(
    (Math.atan2(point[1] - CENTER_Y, point[0] - CENTER_X) * 180) / Math.PI,
  );

const RadarTicks: React.FC = () => {
  return (
    <>
      {ticks.map((angle) => {
        const isCardinal = angle % 90 === 0;
        const isMajor = angle % 15 === 0;
        const inner =
          OUTER_UI_RADIUS - (isCardinal ? 32 : isMajor ? 23 : 14);
        const outer = OUTER_UI_RADIUS - 1;
        const a = polar(inner, angle);
        const b = polar(outer, angle);

        return (
          <line
            key={angle}
            x1={a[0]}
            y1={a[1]}
            x2={b[0]}
            y2={b[1]}
            stroke={isCardinal ? "#a7f8ff" : "#55c9d8"}
            strokeOpacity={isCardinal ? 0.78 : isMajor ? 0.42 : 0.2}
            strokeWidth={isCardinal ? 3 : isMajor ? 2 : 1}
          />
        );
      })}
    </>
  );
};

const CardinalLabels: React.FC = () => {
  const labels = [
    {text: "N", angle: -90},
    {text: "E", angle: 0},
    {text: "S", angle: 90},
    {text: "W", angle: 180},
  ] as const;

  return (
    <>
      {labels.map((label) => {
        const point = polar(SWEEP_RADIUS + 26, label.angle);
        return (
          <text
            key={label.text}
            x={point[0]}
            y={point[1] + 6}
            fill="#c9fbff"
            fillOpacity={0.88}
            fontFamily="Arial, Helvetica, sans-serif"
            fontSize={18}
            fontWeight={700}
            letterSpacing={2}
            textAnchor="middle"
          >
            {label.text}
          </text>
        );
      })}
    </>
  );
};

const DetectionNodes: React.FC<{
  readonly frame: number;
  readonly scanAngle: number;
  readonly reveal: number;
}> = ({frame, scanAngle, reveal}) => {
  const angularSpeed = 360 / 300;

  return (
    <>
      {cityPoints.map((point, index) => {
        const city = cities[index];
        const insideRadar = distanceFromCenter(point) <= SWEEP_RADIUS - 12;
        const delta = normalizeAngle(scanAngle - pointAngle(point));
        const inTrail = insideRadar && delta <= 72;
        const scanLight = inTrail ? 1 - delta / 72 : 0;
        const age = delta / angularSpeed;
        const echoOpacity = inTrail
          ? interpolate(age, [0, 7, 42], [0, 0.95, 0], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            })
          : 0;
        const echoRadius = 8 + Math.min(42, age) * 1.15;
        const pulse =
          0.5 +
          0.5 *
            Math.sin((frame / 78) * TWO_PI + city.phase * TWO_PI);
        const baseOpacity = 0.2 + pulse * 0.16;
        const nodeOpacity = reveal * Math.max(baseOpacity, scanLight);
        const nodeRadius = 3.2 + scanLight * 3.6;

        return (
          <g key={city.name}>
            {insideRadar ? (
              <circle
                cx={point[0]}
                cy={point[1]}
                r={echoRadius}
                fill="none"
                stroke="#74f6ff"
                strokeOpacity={echoOpacity * reveal * 0.8}
                strokeWidth={2}
              />
            ) : null}
            <circle
              cx={point[0]}
              cy={point[1]}
              r={11 + pulse * 3}
              fill="#35e6f2"
              fillOpacity={nodeOpacity * 0.08}
            />
            <circle
              cx={point[0]}
              cy={point[1]}
              r={nodeRadius}
              fill="#b8fbff"
              fillOpacity={nodeOpacity}
              filter={scanLight > 0.15 ? "url(#nodeGlow)" : undefined}
            />
            <circle
              cx={point[0]}
              cy={point[1]}
              r={nodeRadius + 4}
              fill="none"
              stroke="#4dddea"
              strokeOpacity={nodeOpacity * 0.55}
              strokeWidth={1}
            />
          </g>
        );
      })}
    </>
  );
};

export const Motion: React.FC = () => {
  const frame = useCurrentFrame();
  const {durationInFrames} = useVideoConfig();

  const mapReveal = interpolate(
    frame,
    [0, 6, 12, 18, 24, 30, 36, 42],
    [0, 0.13, 0.4, 0.6, 0.77, 0.9, 0.97, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    },
  );
  const sweepReveal = interpolate(
    frame,
    [15, 18, 30, 42, 48],
    [0, 0.25, 0.64, 0.95, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    },
  );
  const radarReveal = interpolate(
    frame,
    [33, 48, 60, 72],
    [0, 0.61, 0.92, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    },
  );
  const nodeReveal = interpolate(frame, [22, 66], [0, 1], {
    easing: Easing.out(Easing.quad),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const scanAngle = ((frame - 79) / 300) * 360;
  const normalizedScanAngle = normalizeAngle(scanAngle);
  const centerPulse = 0.5 + 0.5 * Math.sin((frame / 84) * TWO_PI);
  const ringRotation = -(frame / durationInFrames) * 24;
  const dashOffset = -(frame / durationInFrames) * 28;
  const sweepPower =
    sweepReveal *
    (0.88 + 0.12 * Math.sin((frame / 120) * TWO_PI));

  return (
    <AbsoluteFill
      style={{
        backgroundColor: "#02070d",
        overflow: "hidden",
        fontFamily: "Arial, Helvetica, sans-serif",
      }}
    >
      <AbsoluteFill
        style={{
          background:
            "radial-gradient(circle at 50% 48%, rgba(9,68,82,0.28) 0%, rgba(4,25,36,0.18) 37%, rgba(2,9,16,0.88) 78%, #01050a 100%)",
          opacity: 0.95,
        }}
      />

      <AbsoluteFill
        style={{
          opacity: mapReveal,
          backgroundImage:
            "linear-gradient(rgba(43,155,171,0.025) 1px, transparent 1px), linear-gradient(90deg, rgba(43,155,171,0.025) 1px, transparent 1px)",
          backgroundSize: "96px 96px",
          maskImage:
            "radial-gradient(circle at 50% 50%, black 0%, rgba(0,0,0,0.7) 48%, transparent 88%)",
        }}
      />

      <svg
        width={WIDTH}
        height={HEIGHT}
        viewBox={`0 0 ${WIDTH} ${HEIGHT}`}
        style={{position: "absolute", inset: 0}}
      >
        <defs>
          <filter id="mapGlow" x="-40%" y="-40%" width="180%" height="180%">
            <feGaussianBlur stdDeviation="7" result="blur" />
            <feColorMatrix
              in="blur"
              type="matrix"
              values="0 0 0 0 0.12  0 0 0 0 0.88  0 0 0 0 0.96  0 0 0 0.42 0"
            />
          </filter>
          <filter id="softGlow" x="-80%" y="-80%" width="260%" height="260%">
            <feGaussianBlur stdDeviation="14" result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
          <filter id="lineGlow" x="-100%" y="-100%" width="300%" height="300%">
            <feGaussianBlur stdDeviation="4.5" result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
          <filter id="nodeGlow" x="-250%" y="-250%" width="600%" height="600%">
            <feGaussianBlur stdDeviation="5" result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>

          <pattern
            id="mapDots"
            x="0"
            y="0"
            width="14"
            height="14"
            patternUnits="userSpaceOnUse"
          >
            <circle cx="3" cy="3" r="1.55" fill="#4ac4d2" fillOpacity="0.52" />
            <circle cx="10" cy="10" r="0.75" fill="#5ee0e9" fillOpacity="0.2" />
          </pattern>
          <pattern
            id="mapDotsBright"
            x="0"
            y="0"
            width="12"
            height="12"
            patternUnits="userSpaceOnUse"
          >
            <circle cx="3" cy="3" r="2" fill="#9dfaff" fillOpacity="0.95" />
            <circle cx="9" cy="9" r="1" fill="#66ecf4" fillOpacity="0.55" />
          </pattern>

          <radialGradient
            id="radarWell"
            gradientUnits="userSpaceOnUse"
            cx={CENTER_X}
            cy={CENTER_Y}
            r={SWEEP_RADIUS}
          >
            <stop offset="0%" stopColor="#0ac4d5" stopOpacity="0.07" />
            <stop offset="58%" stopColor="#087184" stopOpacity="0.035" />
            <stop offset="88%" stopColor="#0db4c5" stopOpacity="0.08" />
            <stop offset="100%" stopColor="#0b5060" stopOpacity="0.015" />
          </radialGradient>
          <radialGradient
            id="sweepSurface"
            gradientUnits="userSpaceOnUse"
            cx={CENTER_X}
            cy={CENTER_Y}
            r={SWEEP_RADIUS}
          >
            <stop offset="0%" stopColor="#a9fbff" stopOpacity="0.08" />
            <stop offset="22%" stopColor="#63eff8" stopOpacity="0.14" />
            <stop offset="76%" stopColor="#2bd9e8" stopOpacity="0.34" />
            <stop offset="100%" stopColor="#76f6ff" stopOpacity="0.5" />
          </radialGradient>
          <linearGradient
            id="edgeLine"
            gradientUnits="userSpaceOnUse"
            x1={CENTER_X}
            y1={CENTER_Y}
            x2={CENTER_X + SWEEP_RADIUS}
            y2={CENTER_Y}
          >
            <stop offset="0%" stopColor="#c9fdff" stopOpacity="0.72" />
            <stop offset="55%" stopColor="#8bf7ff" stopOpacity="0.95" />
            <stop offset="100%" stopColor="#d8feff" stopOpacity="1" />
          </linearGradient>

          <clipPath id="radarClip" clipPathUnits="userSpaceOnUse">
            <circle cx={CENTER_X} cy={CENTER_Y} r={SWEEP_RADIUS - 2} />
          </clipPath>
          <clipPath id="sweepClip" clipPathUnits="userSpaceOnUse">
            <path
              d={SWEEP_WIDE}
              transform={`rotate(${scanAngle} ${CENTER_X} ${CENTER_Y})`}
            />
          </clipPath>
        </defs>

        <g opacity={mapReveal}>
          {longitudes.map((longitude) => {
            const x = MAP_LEFT + ((longitude + 180) / 360) * MAP_WIDTH;
            return (
              <line
                key={`lon-${longitude}`}
                x1={x}
                y1={MAP_TOP}
                x2={x}
                y2={MAP_TOP + MAP_HEIGHT}
                stroke="#2f91a0"
                strokeOpacity={longitude === 0 ? 0.14 : 0.075}
                strokeWidth={longitude === 0 ? 1.5 : 1}
                strokeDasharray="2 12"
              />
            );
          })}
          {latitudes.map((latitude) => {
            const y = MAP_TOP + ((90 - latitude) / 180) * MAP_HEIGHT;
            return (
              <line
                key={`lat-${latitude}`}
                x1={MAP_LEFT}
                y1={y}
                x2={MAP_LEFT + MAP_WIDTH}
                y2={y}
                stroke="#2f91a0"
                strokeOpacity={latitude === 0 ? 0.14 : 0.075}
                strokeWidth={latitude === 0 ? 1.5 : 1}
                strokeDasharray="2 12"
              />
            );
          })}

          <path
            d={LAND_PATH}
            fill="#0a2632"
            fillOpacity={0.66}
            stroke="#1f7787"
            strokeOpacity={0.2}
            strokeWidth={8}
            filter="url(#mapGlow)"
          />
          <path
            d={LAND_PATH}
            fill="#0a2632"
            fillOpacity={0.72}
            stroke="#3196a5"
            strokeOpacity={0.34}
            strokeWidth={1.6}
            vectorEffect="non-scaling-stroke"
          />
          <path
            d={LAND_PATH}
            fill="url(#mapDots)"
            fillOpacity={0.78}
            stroke="#48afbd"
            strokeOpacity={0.2}
            strokeWidth={0.8}
          />

          <g opacity={0.26}>
            {links.map(([fromIndex, toIndex], index) => (
              <path
                key={`${fromIndex}-${toIndex}`}
                d={connectionPath(cityPoints[fromIndex], cityPoints[toIndex])}
                fill="none"
                stroke={index % 3 === 0 ? "#50e6ef" : "#2b95aa"}
                strokeWidth={index % 3 === 0 ? 1.6 : 1.1}
                strokeOpacity={index % 3 === 0 ? 0.42 : 0.28}
                strokeDasharray={index % 2 === 0 ? "2 14" : "1 18"}
                strokeDashoffset={dashOffset}
              />
            ))}
          </g>
        </g>

        <g clipPath="url(#radarClip)" opacity={sweepPower}>
          <g transform={`rotate(${scanAngle} ${CENTER_X} ${CENTER_Y})`}>
            <path
              d={SWEEP_WIDE}
              fill="url(#sweepSurface)"
              fillOpacity={0.56}
              filter="url(#softGlow)"
            />
          </g>

          <path
            d={LAND_PATH}
            fill="url(#mapDotsBright)"
            fillOpacity={0.62}
            stroke="#9af9ff"
            strokeOpacity={0.36}
            strokeWidth={1.2}
            clipPath="url(#sweepClip)"
            filter="url(#lineGlow)"
          />

          <g transform={`rotate(${scanAngle} ${CENTER_X} ${CENTER_Y})`}>
            <line
              x1={CENTER_X}
              y1={CENTER_Y}
              x2={CENTER_X + SWEEP_RADIUS}
              y2={CENTER_Y}
              stroke="url(#edgeLine)"
              strokeWidth={3.4}
              filter="url(#lineGlow)"
            />
            <line
              x1={CENTER_X}
              y1={CENTER_Y}
              x2={CENTER_X + SWEEP_RADIUS}
              y2={CENTER_Y}
              stroke="#d7feff"
              strokeOpacity={0.92}
              strokeWidth={1.2}
            />
          </g>
        </g>

        <g opacity={radarReveal}>
          <circle
            cx={CENTER_X}
            cy={CENTER_Y}
            r={SWEEP_RADIUS}
            fill="url(#radarWell)"
            stroke="#54dce8"
            strokeOpacity={0.36}
            strokeWidth={1.5}
          />

          <g clipPath="url(#radarClip)">
            {spokes.map((angle) => {
              const endpoint = polar(SWEEP_RADIUS, angle);
              return (
                <line
                  key={angle}
                  x1={CENTER_X}
                  y1={CENTER_Y}
                  x2={endpoint[0]}
                  y2={endpoint[1]}
                  stroke="#3eb3c2"
                  strokeOpacity={angle % 90 === 0 ? 0.18 : 0.085}
                  strokeWidth={angle % 90 === 0 ? 1.2 : 0.8}
                  strokeDasharray={angle % 90 === 0 ? "none" : "3 10"}
                />
              );
            })}

          </g>

          {ringRadii.map((radius, index) => (
            <circle
              key={radius}
              cx={CENTER_X}
              cy={CENTER_Y}
              r={radius}
              fill="none"
              stroke={index === ringRadii.length - 1 ? "#58dce8" : "#2c91a0"}
              strokeOpacity={index === ringRadii.length - 1 ? 0.26 : 0.19}
              strokeWidth={index === ringRadii.length - 1 ? 1.5 : 1}
              strokeDasharray={index % 2 === 0 ? "3 9" : undefined}
            />
          ))}

          <circle
            cx={CENTER_X}
            cy={CENTER_Y}
            r={SWEEP_RADIUS + 14}
            fill="none"
            stroke="#45bfce"
            strokeOpacity={0.27}
            strokeWidth={1}
            strokeDasharray="1 8"
            transform={`rotate(${ringRotation} ${CENTER_X} ${CENTER_Y})`}
          />
          <circle
            cx={CENTER_X}
            cy={CENTER_Y}
            r={SWEEP_RADIUS + 28}
            fill="none"
            stroke="#7aeef5"
            strokeOpacity={0.2}
            strokeWidth={1}
            strokeDasharray="24 7 2 10"
            transform={`rotate(${-ringRotation * 0.65} ${CENTER_X} ${CENTER_Y})`}
          />

          <RadarTicks />
          <CardinalLabels />
        </g>

        <DetectionNodes
          frame={frame}
          scanAngle={normalizedScanAngle}
          reveal={nodeReveal}
        />

        <g opacity={radarReveal}>
          <circle
            cx={CENTER_X}
            cy={CENTER_Y}
            r={44 + centerPulse * 7}
            fill="#45e9f4"
            fillOpacity={0.025 + centerPulse * 0.025}
            stroke="#70f1f8"
            strokeOpacity={0.12 + centerPulse * 0.1}
            strokeWidth={1.4}
          />
          <circle
            cx={CENTER_X}
            cy={CENTER_Y}
            r={24 + centerPulse * 4}
            fill="none"
            stroke="#8ef8ff"
            strokeOpacity={0.24 + centerPulse * 0.2}
            strokeWidth={1.4}
          />
          <circle
            cx={CENTER_X}
            cy={CENTER_Y}
            r={12}
            fill="#2de4ef"
            fillOpacity={0.24}
            filter="url(#softGlow)"
          />
          <circle
            cx={CENTER_X}
            cy={CENTER_Y}
            r={5.4 + centerPulse * 1.4}
            fill="#d5feff"
            fillOpacity={0.96}
            filter="url(#nodeGlow)"
          />
          <circle
            cx={CENTER_X}
            cy={CENTER_Y}
            r={2.2}
            fill="#ffffff"
          />
        </g>

        <g opacity={mapReveal * 0.9}>
          {specks.map((speck, index) => {
            const twinkle =
              0.55 +
              0.45 *
                Math.sin((frame / 150) * TWO_PI + speck.phase);
            return (
              <circle
                key={index}
                cx={speck.x}
                cy={speck.y}
                r={speck.radius}
                fill="#76dce5"
                fillOpacity={speck.opacity * twinkle}
              />
            );
          })}
        </g>
      </svg>

      <AbsoluteFill
        style={{
          pointerEvents: "none",
          opacity: 0.2,
          backgroundImage:
            "repeating-linear-gradient(180deg, rgba(118,232,241,0.05) 0px, rgba(118,232,241,0.05) 1px, transparent 1px, transparent 5px)",
          mixBlendMode: "screen",
        }}
      />

      <AbsoluteFill
        style={{
          pointerEvents: "none",
          boxShadow:
            "inset 0 0 180px rgba(0,0,0,0.82), inset 0 0 420px rgba(0,0,0,0.46)",
          background:
            "radial-gradient(circle at 50% 50%, transparent 0%, transparent 45%, rgba(0,7,13,0.18) 70%, rgba(0,3,8,0.72) 100%)",
        }}
      />
    </AbsoluteFill>
  );
};
